mapper.select:
select help.partyHelpID,help.userCode,help.year,help.recordStatus,help.approveUserID,help.createTime, help.createUserId, help.createUserName, help.updateTime, help.updateUserId,help.updateUserName,help.helpReason,help.approveTime ,us.XM as userName,zz.DZZMC as partyName,zz.DZZDM as partyCode,approveUser.XM as approveUserName,dic.DICVALUE as recordStatusName,userinfo.USERNAME as userNo from us_partyhelp help inner join vm_ryjbxx us on help.userCode = us.RYBM inner join zz_zzqkxx zz on us.SZDZBDM = zz.DZZDM left join vm_ryjbxx approveUser on help.approveUserID = approveUser.RYBM left join cf_dictionary dic on help.recordStatus = dic.DICKEY and dic.DICTYPEKEY = 'partyHelpStatus' left join CF_USERS userinfo on us.RYBM=userinfo.USERID
and help.partyHelpID = #{partyHelpID}
and us.SZDZBDM like concat(#{partyCode},'%')
and us.XM like concat('%',#{userName},'%')
and us.RYBM like concat('%',#{userCode},'%')
and help.year = #{year}
and help.recordStatus = #{recordStatus}
and concat(us.XM,zz.DZZMC,help.year) in
#{name}
order by help.year desc,zz.DZZDM,us.RYBM

mapper.update:
update us_partyhelp set approveUserID=#{approveUserID},approveTime=sysdate(),recordStatus=#{approveResult}
where partyHelpID in

    #{id}
